1	// One entry of the shared manufacturing-revision timeline, rendered inline
2	// where it happened in the conversation. Revert here is destructive and
3	// always asks at action time: the button expands into an explicit inline
4	// confirmation before anything is sent to the host.
5	
6	import { useState } from 'react';
7	import { RevisionInfo } from '../bridge/protocol';
8	
9	interface Props {
10	  revision: RevisionInfo;
11	  onRevert: (revisionId: string) => void;
12	}
13	
14	export function RevisionMarker({ revision, onRevert }: Props) {
15	  const [confirming, setConfirming] = useState(false);
16	
17	  return (
18	    <div className={revision.current ? 'revision-marker current' : 'revision-marker'} data-testid={`revision-${revision.id}`}>
19	      <span className="revision-label">
20	        {revision.cause === 'initial' ? 'Project start' : `Project changed (${revision.cause})`}
21	        {revision.current && ' — current'}
22	      </span>
23	      {!revision.current && revision.revertible && !confirming && (
24	        <button onClick={() => setConfirming(true)}>Revert here</button>
25	      )}
26	      {confirming && (
27	        <span className="revision-confirm" role="alertdialog" aria-label="Confirm revert">
28	          Reverting permanently removes everything after this point — later messages, approvals, and project changes in
29	          every conversation. This cannot be undone.
30	          <button
31	            className="primary"
32	            onClick={() => {
33	              setConfirming(false);
34	              onRevert(revision.id);
35	            }}
36	          >
37	            Revert permanently
38	          </button>
39	          <button onClick={() => setConfirming(false)}>Keep everything</button>
40	        </span>
41	      )}
42	      {!revision.current && !revision.revertible && <span className="revision-label">No checkpoint available</span>}
43	    </div>
44	  );
45	}
