86	std::string cause_of(WorkspaceChangeReasons reasons)
87	{
88	    std::string cause;
89	    const auto add = [&cause](const char* name) {
90	        if (!cause.empty())
91	            cause += "+";
92	        cause += name;
93	    };
94	    if (has_reason(reasons, WorkspaceChangeReasons::Contents))
95	        add("contents");
96	    if (has_reason(reasons, WorkspaceChangeReasons::Transform))
97	        add("transform");
98	    if (has_reason(reasons, WorkspaceChangeReasons::Plates))
99	        add("plates");
100	    if (has_reason(reasons, WorkspaceChangeReasons::History))
101	        add("history");
102	    return cause.empty() ? "change" : cause;
103	}
