142	void ProjectPersistence::on_workspace_changed(const Workspace::WorkspaceChanged& change)
143	{
144	    if (m_in_revert)
145	        return;
146	    if (has_reason(change.reasons, WorkspaceChangeReasons::Project)) {
147	        if (!m_attached || m_workspace.auxiliary_data_dir() != m_attached_aux_dir) {
148	            // The new project's directory is already in place: adopt it.
149	            adopt_current_project(/*in_place_reset=*/false);
150	        } else {
151	            // Ambiguous: either an in-place full reset, or a replacement
152	            // whose event was published before the directory moved. Park the
153	            // decision until the directory settles.
154	            m_boundary_pending = true;
155	        }
156	        return;
157	    }
158	    if (heal_if_directory_moved())
159	        return;
160	    if (m_boundary_pending) {
161	        // A later event with the directory still in place means the project
162	        // operation completed without moving it: an in-place reset.
163	        resolve_pending_boundary();
164	        return;
165	    }
166	    if (!m_attached || !m_document.has_identity())
167	        return;
168	    if ((change.reasons & kManufacturingReasons) != WorkspaceChangeReasons::None) {
169	        // The pre-change state is gone; a missing initial checkpoint can no
170	        // longer be backfilled.
171	        m_initial_capture_pending = false;
172	        capture_revision(cause_of(change.reasons));
173	        return;
174	    }
175	    if (m_initial_capture_pending)
176	        retry_initial_capture();
177	}
