179	bool ProjectPersistence::heal_if_directory_moved()
180	{
181	    // The authoritative auxiliary directory is the single source of truth
182	    // for project identity on disk. Whenever it no longer matches the
183	    // attached one — however the boundary events were ordered or raced —
184	    // adopt what is actually there.
185	    if (!m_attached || m_workspace.auxiliary_data_dir() == m_attached_aux_dir)
186	        return false;
187	    m_boundary_pending = false;
188	    adopt_current_project(/*in_place_reset=*/false);
189	    return true;

