34	WorkspaceObject project_object(ProjectSessionId session, const ModelObject& object, PartPlate& plate, int object_index)
35	{
36	    WorkspaceObject projected;
37	    projected.id   = ObjectId(session, object.id().id);
38	    projected.name = object.name;
39	    projected.instances.reserve(object.instances.size());
40	    for (std::size_t instance_index = 0; instance_index < object.instances.size(); ++instance_index)
41	        if (plate.contain_instance(object_index, static_cast<int>(instance_index)))
42	            projected.instances.emplace_back(transform_of(*object.instances[instance_index]));
43	    return projected;
44	}
