46	WorkspaceChangeReasons workspace_reasons(ProjectStateChangeReason reasons)
47	{
48	    WorkspaceChangeReasons result = WorkspaceChangeReasons::None;
49	    const auto contains = [reasons](ProjectStateChangeReason reason) {
50	        return (static_cast<std::uint32_t>(reasons) & static_cast<std::uint32_t>(reason)) != 0;
51	    };
52	    if (contains(ProjectStateChangeReason::Selection))
53	        result |= WorkspaceChangeReasons::Selection;
54	    if (contains(ProjectStateChangeReason::Objects))
55	        result |= WorkspaceChangeReasons::Contents;
56	    if (contains(ProjectStateChangeReason::History))
57	        result |= WorkspaceChangeReasons::History;
58	    if (contains(ProjectStateChangeReason::Transform))
59	        result |= WorkspaceChangeReasons::Transform;
60	    if (contains(ProjectStateChangeReason::Plates))
61	        result |= WorkspaceChangeReasons::Plates;
62	    if (contains(ProjectStateChangeReason::Project))
63	        result |= WorkspaceChangeReasons::Project;
64	    if (contains(ProjectStateChangeReason::Settings))
65	        result |= WorkspaceChangeReasons::Settings;
66	    return result;
67	}
