74	// Time and material for one plate, read from the plate's own G-code result the
75	// same way Orca's preview and cost readouts do: volume per extruder times that
76	// filament's density and price. Nothing here is computed by JusPrin, so the
77	// card can never disagree with the number the slicer shows.
78	std::optional<SliceEstimate> estimate_of(const GCodeProcessorResult& result)
79	{
80	    SliceEstimate estimate;
81	    const auto& statistics = result.print_statistics;
82	    const auto& mode = statistics.modes[static_cast<std::size_t>(PrintEstimatedStatistics::ETimeMode::Normal)];
83	    estimate.print_time_seconds = mode.time > 0.f ? static_cast<std::uint32_t>(mode.time) : 0u;
84	
85	    double cost = 0.0;
86	    bool   every_filament_priced = true;
87	    for (const auto& [extruder, volume] : statistics.total_volumes_per_extruder) {
88	        // A slice that used an extruder Orca has no density for cannot be
89	        // weighed, and a partial weight presented as the total is worse than
90	        // no weight at all -- so the whole estimate goes.
91	        if (extruder >= result.filament_densities.size()) return std::nullopt;
92	        const double grams = volume * result.filament_densities[extruder] * 0.001;
93	        estimate.material_grams += grams;
94	        // A filament profile with no price reports zero, which is not a price.
95	        if (extruder < result.filament_costs.size() && result.filament_costs[extruder] > 0.f)
96	            cost += grams * result.filament_costs[extruder] * 0.001;
97	        else
98	            every_filament_priced = false;
99	    }
100	    // Money is the cost of the whole print or it is not shown. With one spool
101	    // priced and another not, a "total" would silently leave material out.
102	    estimate.has_cost      = every_filament_priced && cost > 0.0;
103	    estimate.material_cost = estimate.has_cost ? cost : 0.0;
104	    // A slice that produced no material is not an estimate worth a row.
105	    if (estimate.print_time_seconds == 0 && estimate.material_grams <= 0.0) return std::nullopt;
106	    return estimate;
107	}
