109	// Every process setting whose value in force differs from the preset it was
110	// loaded from -- the card's "N changes from preset". Keys Orca reports but no
111	// longer defines are skipped rather than shown without a label.
112	std::vector<PresetDelta> preset_deltas_of(const PresetCollection& prints, const std::vector<std::string>& dirty)
113	{
114	    std::vector<PresetDelta> result;
115	    result.reserve(dirty.size());
116	    const DynamicPrintConfig& edited = prints.get_edited_preset().config;
117	    const DynamicPrintConfig& saved  = prints.get_selected_preset().config;
118	    for (const std::string& key : dirty) {
119	        const ConfigOptionDef* definition = print_config_def.get(key);
120	        const ConfigOption*    before     = saved.option(key);
121	        const ConfigOption*    after      = edited.option(key);
122	        if (definition == nullptr || before == nullptr || after == nullptr) continue;
123	        const std::string& label = definition->full_label.empty() ? definition->label : definition->full_label;
124	        result.push_back({key, label.empty() ? key : label, before->serialize(), after->serialize()});
125	    }
126	    return result;
127	}
