131	OrcaWorkspaceAdapter::OrcaWorkspaceAdapter(Plater& plater) : m_plater(plater)
132	{
133	    wxASSERT(wxIsMainThread());
134	    m_session = ProjectSessionId(m_plater.project_state_session());
135	    m_project_subscription = m_plater.subscribe_project_state(
136	        [this](const ProjectStateChanged& change) { on_project_state_changed(change); });
137	    // Slicing changes what a plate holds without changing the project, so it
138	    // raises no ProjectStateChanged and consumers would keep reporting the
139	    // plate unsliced until something unrelated moved. The header already
140	    // listens to this event; the workspace has to as well, or an estimate only
141	    // appears after the next click.
142	    m_plater.Bind(EVT_SLICE_STATUS_CHANGED, &OrcaWorkspaceAdapter::on_slice_status_changed, this);
143	    m_known_slice_state = current_slice_state();
144	    remember_current_ids();
145	}
