154	OrcaWorkspaceAdapter::SliceState OrcaWorkspaceAdapter::current_slice_state() const
155	{
156	    SliceState state;
157	    // Whether a slice is running is part of what the plate holds, not merely
158	    // progress: starting one on an already-invalid plate changes neither the
159	    // valid flag nor the result id, so without it that transition publishes
160	    // nothing and no consumer ever learns the slice began.
161	    const bool slicing = m_plater.is_background_process_slicing();
162	    PartPlateList& plates = m_plater.get_partplate_list();
163	    for (int index = 0; index < plates.get_plate_count(); ++index) {
164	        PartPlate* plate = plates.get_plate(index);
165	        if (plate == nullptr) continue;
166	        const bool sliced = plate->is_slice_result_valid();
167	        const std::uint64_t result = sliced && !slicing && plate->get_slice_result() ?
168	            plate->get_slice_result()->id : 0;
169	        state.emplace(plate->id().id, PlateSlice{sliced, result, slicing});
170	    }
171	    return state;
172	}
