174	void OrcaWorkspaceAdapter::on_slice_status_changed(wxCommandEvent& event)
175	{
176	    event.Skip();
177	    wxASSERT(wxIsMainThread());
178	    // This event also fires whenever the native toolbar re-evaluates whether
179	    // Slice and Print are enabled, which happens on ordinary selection and
180	    // object changes. Publishing on all of those would advance the revision --
181	    // and add a history entry -- for nothing. Only a real change in what the
182	    // plates hold is a workspace change.
183	    SliceState state = current_slice_state();
