204	void ProjectPersistence::adopt_current_project(bool in_place_reset)
205	{
206	    m_attached_aux_dir = m_workspace.auxiliary_data_dir();
207	    m_attached         = true;
208	    m_draft.clear();
209	
210	    if (in_place_reset) {
211	        // A full in-place reset is a new project boundary: earlier state does
212	        // not carry into it.
213	        std::error_code ec;
214	        fs::remove_all(jusprin_data_dir(), ec);
215	        start_fresh_identity();
216	        return;
217	    }
218	
219	    const std::string state_text = read_file(state_file_path());
220	    if (state_text.empty()) {
221	        start_fresh_identity();
222	        return;
223	    }
224	
225	    ProjectStateDocument loaded;
226	    const ProjectStateDocument::LoadResult result = loaded.load(state_text);
227	    if (result == ProjectStateDocument::LoadResult::Corrupt) {
228	        // Keep the unreadable file for inspection, then start over.
229	        std::error_code ec;
230	        fs::rename(state_file_path(), state_file_path() + ".corrupt", ec);
231	        start_fresh_identity();
232	        return;
233	    }
234	    m_document = std::move(loaded);
235	
236	    // The recovery mirror may hold state newer than the last explicit save
237	    // (messages, approvals, a partial reply from before a crash).
238	    const std::string recovery = recovery_dir();
239	    if (!recovery.empty()) {
240	        const std::string mirror_text = read_file(fs::path(recovery) / kStateFileName);
241	        if (!mirror_text.empty()) {
242	            ProjectStateDocument mirror;
243	            if (mirror.load(mirror_text) != ProjectStateDocument::LoadResult::Corrupt &&
244	                mirror.project_id() == m_document.project_id() && mirror.doc_revision() > m_document.doc_revision())
245	                m_document = std::move(mirror);
246	        }
247	        load_recovery_meta();
248	    }
249	
250	    // A stream or run interrupted by the crash/restart cannot resume.
251	    m_document.normalize_interrupted_state();
252	
253	    m_dirty = true;
254	    flush();
255	    notify_document_replaced();
256	}
