280	void ProjectPersistence::retry_initial_capture()
281	{
282	    const std::vector<RevisionInfo> revisions = m_document.revisions();
283	    if (revisions.empty() || !revisions.front().snapshot_file.empty() ||
284	        m_document.current_revision_id() != revisions.front().id) {
285	        m_initial_capture_pending = false;
286	        return;
287	    }
288	    const RevisionInfo& initial  = revisions.front();
289	    const std::string   relative = std::string(kRevisionsDir) + "/" + initial.id + kSnapshotSuffix;
290	    const fs::path      target   = fs::path(jusprin_data_dir()) / kRevisionsDir / (initial.id + kSnapshotSuffix);
291	    std::error_code ec;
292	    fs::create_directories(target.parent_path(), ec);
293	    if (!m_workspace.export_project_archive(target.string()).succeeded())
294	        return; // still not ready; keep retrying on later events
295	    m_initial_capture_pending = false;
296	    ++m_stats.captures;
297	    m_stats.total_snapshot_bytes += fs::file_size(target, ec);
298	    m_document.set_revision_snapshot(initial.id, relative);
299	    m_dirty = true;
300	    flush();
301	}
