303	void ProjectPersistence::capture_revision(const std::string& cause)
304	{
305	    const std::string revision_id = m_document.peek_next_revision_id();
306	    const std::string relative    = std::string(kRevisionsDir) + "/" + revision_id + kSnapshotSuffix;
307	    const fs::path    target      = fs::path(jusprin_data_dir()) / kRevisionsDir / (revision_id + kSnapshotSuffix);
308	
309	    std::error_code ec;
