311	
312	    const auto started = std::chrono::steady_clock::now();
313	    const Workspace::CommandResult exported = m_workspace.export_project_archive(target.string());
314	    m_stats.last_capture_ms =
315	        std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - started).count();
316	
317	    std::string snapshot_file;
318	    if (exported.succeeded()) {
319	        snapshot_file = relative;
320	        ++m_stats.captures;
321	        m_stats.total_snapshot_bytes += fs::file_size(target, ec);
322	    } else {
323	        // Record the revision honestly without a checkpoint; it cannot be
324	        // reverted to, but the timeline stays truthful.
325	        ++m_stats.capture_failures;
